const lines=load("c4_manifest_lines").trim().split("\n");
const map={}; for(const line of lines){const m=line.match(/^([0-9a-f]{64})  (.*)$/);if(!m)throw Error("bad manifest line");map[m[2].replace("/tmp/development-review-19-c4/","")]=m[1];}
const compact=JSON.stringify(map);
const spaced="{"+Object.entries(map).map(([k,v])=>JSON.stringify(k)+": "+JSON.stringify(v)).join(", ")+"}";
store("c4_manifest_compact",compact);store("c4_manifest_spaced",spaced);
const rs=await Promise.allSettled([compact,spaced].map((v)=>tools.exec_command({cmd:"printf '%s' '"+v+"' | sha256sum","workdir":"/tmp","max_output_tokens":1000})));rs.forEach((r,i)=>text({encoding:i===0?"relative keys, compact JSON, no terminal newline":"relative keys, JSON spaces after colon/comma, no terminal newline",...(r.status==="fulfilled"?{output:r.value.output}:{error:String(r.reason)})}));

const map=JSON.parse(load("c4_manifest_compact"));
const variants=[];
for(const absolute of [false,true]){
const m=absolute?Object.fromEntries(Object.entries(map).map(([k,v])=>["/tmp/development-review-19-c4/"+k,v])):map;
for(const style of ["compact","spaced","indent2","indent4"]){
let s=style==="compact"?JSON.stringify(m):style==="spaced"?"{"+Object.entries(m).map(([k,v])=>JSON.stringify(k)+": "+JSON.stringify(v)).join(", ")+"}":JSON.stringify(m,null,style==="indent2"?2:4);
for(const newline of [false,true])variants.push({name:(absolute?"absolute":"relative")+"-"+style+(newline?"-newline":""),s:s+(newline?"\n":"")});}}
const rs=await Promise.allSettled(variants.map(v=>tools.exec_command({cmd:"printf '%s' '"+v.s+"' | sha256sum","workdir":"/tmp","max_output_tokens":100})));
rs.forEach((r,i)=>{if(r.status==="rejected")text({name:variants[i].name,error:String(r.reason)});else text({name:variants[i].name,sha:r.value.output.trim().split(" ")[0]});});
store("c4_audit_variants",rs.map((r,i)=>({name:variants[i].name,...(r.status==="fulfilled"?{sha:r.value.output.trim().split(" ")[0]}:{error:String(r.reason)})})));

const r=await tools.exec_command({cmd:"rg --files --hidden -a /tmp/development-review-19-c4 | sort | xargs sha256sum","workdir":"/tmp","max_output_tokens":6500}); store("c4_full_manifest_lines",r.output);
const map={}; for(const line of r.output.trim().split("\n")){const m=line.match(/^([0-9a-f]{64})  (.*)$/);if(!m)throw Error("bad manifest");map[m[2].replace("/tmp/development-review-19-c4/","")]=m[1];}
const json="{"+Object.entries(map).map(([k,v])=>JSON.stringify(k)+": "+JSON.stringify(v)).join(", ")+"}";
store("c4_full_manifest_json",json);
text({files:Object.keys(map).length});
text((await tools.exec_command({cmd:"printf '%s' '"+json+"' | sha256sum","workdir":"/tmp","max_output_tokens":200})).output);
text(await tools.apply_patch("*** Begin Patch\n*** Add File: /tmp/development-review-19-spec-c4-source-manifest.json\n+"+json+"\n*** End Patch"));

const rs=await Promise.allSettled([
tools.exec_command({cmd:"cat /tmp/development-review-19-spec-c4-report.md","workdir":"/tmp","max_output_tokens":15000}),
tools.exec_command({cmd:"rg --files --hidden -a /tmp/development-review-19-c4 | sort | xargs sha256sum","workdir":"/tmp","max_output_tokens":7000}),
tools.exec_command({cmd:"sha256sum /tmp/development-review-19-spec-c4-report.md /tmp/development-review-19-spec-c4-source-manifest.json","workdir":"/tmp","max_output_tokens":500})
]);
for(let i=0;i<rs.length;i++){const r=rs[i];if(r.status!=="fulfilled"){text({check:i,error:String(r.reason)});continue;}if(i===0)text({saved_report_matches_original:r.value.output===load("c4_final_report"),saved_report_chars:r.value.output.length});if(i===1)text({snapshot_file_digests_unchanged:r.value.output===load("c4_full_manifest_lines")});if(i===2)text(r.value.output);}
